1	import { useState } from "react";
2	import { toast } from "sonner";
3	import { format } from "date-fns";
4	import {
5	  Users,
6	  Crown,
7	  Shield,
8	  UserPlus,
9	  Trash2,
10	  Loader2,
11	  Mail,
12	  RotateCw,
13	  Briefcase,
14	  FileText,
15	  CheckSquare,
16	  ArrowRight,
17	  AlertCircle,
18	} from "lucide-react";
19	import { Link } from "react-router-dom";
20	import SidebarLayout from "@/components/SidebarLayout";
21	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
22	import { Button } from "@/components/ui/button";
23	import { Input } from "@/components/ui/input";
24	import { Badge } from "@/components/ui/badge";
25	import { Skeleton } from "@/components/ui/skeleton";
26	import {
27	  Select,
28	  SelectContent,
29	  SelectItem,
30	  SelectTrigger,
31	  SelectValue,
32	} from "@/components/ui/select";
33	import {
34	  Table,
35	  TableBody,
36	  TableCell,
37	  TableHead,
38	  TableHeader,
39	  TableRow,
40	} from "@/components/ui/table";
41	import {
42	  AlertDialog,
43	  AlertDialogAction,
44	  AlertDialogCancel,
45	  AlertDialogContent,
46	  AlertDialogDescription,
47	  AlertDialogFooter,
48	  AlertDialogHeader,
49	  AlertDialogTitle,
50	  AlertDialogTrigger,
51	} from "@/components/ui/alert-dialog";
52	import { useTeam, type TeamMember, type TeamInvitation } from "@/hooks/useTeam";
53	import PipelineStageManager from "@/components/PipelineStageManager";
54	import ScorecardTemplateManager from "@/components/ScorecardTemplateManager";
55	import StageAutomationManager from "@/components/StageAutomationManager";
56	import { useTeamDashboard } from "@/hooks/useTeamDashboard";
57	import ActivityItem from "@/components/ActivityItem";
58	import { supabase } from "@/integrations/supabase/client";
59	import { useAuth } from "@/hooks/useAuth";
60	
61	type TeamRole = "owner" | "admin" | "member";
62	
63	const ROLE_LABELS: Record<TeamRole, string> = {
64	  owner: "Owner",
65	  admin: "Admin",
66	  member: "Member",
67	};
68	
69	const ROLE_VARIANTS: Record<TeamRole, "default" | "secondary" | "outline"> = {
70	  owner: "default",
71	  admin: "secondary",
72	  member: "outline",
73	};
74	
75	function RoleBadge({ role }: { role: TeamRole }) {
76	  const Icon = role === "owner" ? Crown : role === "admin" ? Shield : Users;
77	  return (
78	    <Badge variant={ROLE_VARIANTS[role]} className="gap-1 text-xs font-medium">
79	      <Icon className="h-3 w-3" />
80	      {ROLE_LABELS[role]}
81	    </Badge>
82	  );
83	}
84	
85	function MembersSkeleton() {
86	  return (
87	    <div className="space-y-3">
88	      {[1, 2, 3].map((i) => (
89	        <div key={i} className="flex items-center gap-4 px-4 py-3">
90	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
91	          <div className="flex-1 space-y-1.5">
92	            <Skeleton className="h-4 w-48" />
93	            <Skeleton className="h-3 w-32" />
94	          </div>
95	          <Skeleton className="h-6 w-16 rounded-full" />
96	          <Skeleton className="h-8 w-8 rounded" />
97	        </div>
98	      ))}
99	    </div>
100	  );
101	}
102	
103	const Team = () => {
104	  const { user } = useAuth();
105	  const { team, members, invitations, myRole, isLoading, error, refetch } = useTeam();
106	
107	  const [inviteEmail, setInviteEmail] = useState("");
108	  const [inviteRole, setInviteRole] = useState<"admin" | "member">("member");
109	  const [isSendingInvite, setIsSendingInvite] = useState(false);
110	  const [revokingId, setRevokingId] = useState<string | null>(null);
111	  const [removingId, setRemovingId] = useState<string | null>(null);
112	  const [updatingRoleId, setUpdatingRoleId] = useState<string | null>(null);
113	
114	  const canManage = myRole === "owner" || myRole === "admin";
115	
116	  async function handleInvite(e: React.FormEvent) {
117	    e.preventDefault();
118	    if (!inviteEmail.trim() || !team?.id) return;
119	
120	    setIsSendingInvite(true);
121	    try {
122	      const { data: { session } } = await supabase.auth.getSession();
123	      if (!session?.access_token) throw new Error("Not authenticated");
124	
125	      const res = await fetch(
126	        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-team-invite`,
127	        {
128	          method: "POST",
129	          headers: {
130	            "Content-Type": "application/json",
131	            "Authorization": `Bearer ${session.access_token}`,
132	            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
133	          },
134	          body: JSON.stringify({
135	            team_id: team.id,
136	            email: inviteEmail.trim().toLowerCase(),
137	            role: inviteRole,
138	          }),
139	        }
140	      );
141	
142	      const json = await res.json();
143	      if (!res.ok) throw new Error(json.error || "Failed to send invitation");
144	
145	      toast.success(`Invitation sent to ${inviteEmail.trim()}`);
146	      setInviteEmail("");
147	      refetch();
148	    } catch (err: unknown) {
149	      const msg = err instanceof Error ? err.message : "Failed to send invitation";
150	      toast.error(msg);
151	    } finally {
152	      setIsSendingInvite(false);
153	    }
154	  }
155	
156	  async function handleRevokeInvite(id: string, email: string) {
157	    setRevokingId(id);
158	    try {
159	      const { error } = await (supabase as any)
160	        .from("team_invitations")
161	        .update({ status: "revoked" })
162	        .eq("id", id);
163	
164	      if (error) throw error;
165	
166	      toast.success(`Invitation to ${email} revoked`);
167	      refetch();
168	    } catch (err: unknown) {
169	      toast.error("Failed to revoke invitation");
170	    } finally {
171	      setRevokingId(null);
172	    }
173	  }
174	
175	  async function handleChangeRole(member: TeamMember, newRole: TeamRole) {
176	    if (newRole === member.role) return;
177	    setUpdatingRoleId(member.id);
178	    try {
179	      const { error } = await (supabase as any)
180	        .from("team_members")
181	        .update({ role: newRole })
182	        .eq("id", member.id);
183	
184	      if (error) throw error;
185	
186	      toast.success(`Role updated to ${ROLE_LABELS[newRole]}`);
187	      refetch();
188	    } catch (err: unknown) {
189	      toast.error("Failed to update role");
190	    } finally {
191	      setUpdatingRoleId(null);
192	    }
193	  }
194	
195	  async function handleRemoveMember(member: TeamMember) {
196	    setRemovingId(member.id);
197	    try {
198	      const { error } = await (supabase as any)
199	        .from("team_members")
200	        .delete()
201	        .eq("id", member.id);
202	
203	      if (error) throw error;
204	
205	      toast.success("Member removed from team");
206	      refetch();
207	    } catch (err: unknown) {
208	      toast.error("Failed to remove member");
209	    } finally {
210	      setRemovingId(null);
211	    }
212	  }
213	
214	  const pendingInvitations = invitations.filter((inv) => inv.status === "pending");
215	  const nonOwnerMembers = members.filter((m) => m.role !== "owner");
216	
217	  const { data: dashboard, isLoading: dashLoading } = useTeamDashboard(team?.id ?? null);
218	
219	  // Stat cards config
220	  const statCards = [
221	    {
222	      icon: Briefcase,
223	      label: "Total Jobs",
224	      value: dashboard?.totalJobs ?? 0,
225	    },
226	    {
227	      icon: FileText,
228	      label: "Active Candidates",
229	      value: dashboard?.activeCandidates ?? 0,
230	    },
231	    {
232	      icon: CheckSquare,
233	      label: "Pending Tasks",
234	      value: dashboard?.pendingTasks ?? 0,
235	    },
236	    {
237	      icon: Users,
238	      label: "Team Members",
239	      value: dashboard?.memberCount ?? 0,
240	    },
241	  ];
242	
243	  return (
244	    <SidebarLayout>
245	      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
246	        <div className="flex items-center justify-between mb-1">
247	          <h1 className="text-2xl font-bold text-foreground">Team</h1>
248	          {team && (
249	            <span className="text-sm text-muted-foreground">{team.name}</span>
250	          )}
251	        </div>
252	        <p className="text-sm text-muted-foreground mb-6">
253	          Manage your team members and pending invitations.
254	        </p>
255	
256	        {/* Error state */}
257	        {!isLoading && error && (
258	          <Card className="border-destructive/50 mb-6">
259	            <CardContent className="py-8 text-center">
260	              <AlertCircle className="h-8 w-8 text-destructive mx-auto mb-2" />
261	              <p className="text-sm text-muted-foreground">Failed to load data. Please refresh the page.</p>
262	            </CardContent>
263	          </Card>
264	        )}
265	
266	        {/* ── Dashboard section (only when team exists) ── */}
267	        {team && (
268	          <div className="space-y-4 mb-6">
269	            {/* Stats row */}
270	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
271	              {statCards.map(({ icon: Icon, label, value }) => (
272	                <Card key={label} className="border border-border/60 shadow-sm">
273	                  <CardContent className="p-4">
274	                    <div className="flex items-center gap-2.5 mb-2">
275	                      <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
276	                        <Icon className="h-4 w-4 text-primary" />
277	                      </div>
278	                    </div>
279	                    {dashLoading ? (
280	                      <Skeleton className="h-7 w-12 mb-1" />
281	                    ) : (
282	                      <p className="text-2xl font-bold text-foreground">{value}</p>
283	                    )}
284	                    <p className="text-xs text-muted-foreground">{label}</p>
285	                  </CardContent>
286	                </Card>
287	              ))}
288	            </div>
289	
290	            {/* Recent Activity card */}
291	            <Card className="border border-border/60 shadow-sm">
292	              <CardHeader className="pb-2 pt-4">
293	                <div className="flex items-center justify-between">
294	                  <CardTitle className="text-sm font-semibold">Recent Activity</CardTitle>
295	                  <Link
296	                    to="/activity"
297	                    className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors font-medium"
298	                  >
299	                    View all
300	                    <ArrowRight className="h-3 w-3" />
301	                  </Link>
302	                </div>
303	              </CardHeader>
304	              <CardContent className="pb-3">
305	                {dashLoading ? (
306	                  <div className="space-y-2">
307	                    {[1, 2, 3].map((i) => (
308	                      <Skeleton key={i} className="h-9 w-full rounded-lg" />
309	                    ))}
310	                  </div>
311	                ) : !dashboard?.recentActivity.length ? (
312	                  <p className="text-sm text-muted-foreground py-2">No activity yet</p>
313	                ) : (
314	                  <div className="divide-y divide-border/40">
315	                    {dashboard.recentActivity.map((activity) => (
316	                      <ActivityItem key={activity.id} activity={activity} compact />
317	                    ))}
318	                  </div>
319	                )}
320	              </CardContent>
321	            </Card>
322	
323	            {/* Task summary by assignee */}
324	            {!dashLoading && dashboard?.tasksByAssignee && dashboard.tasksByAssignee.length > 0 && (
325	              <Card className="border border-border/60 shadow-sm">
326	                <CardHeader className="pb-2 pt-4">
327	                  <CardTitle className="text-sm font-semibold">Task Summary by Member</CardTitle>
328	                </CardHeader>
329	                <CardContent className="p-0">
330	                  <Table>
331	                    <TableHeader>
332	                      <TableRow>
333	                        <TableHead className="text-xs">Member</TableHead>
334	                        <TableHead className="text-xs text-right">Pending</TableHead>
335	                        <TableHead className="text-xs text-right">Completed</TableHead>
336	                      </TableRow>
337	                    </TableHeader>
338	                    <TableBody>
339	                      {dashboard.tasksByAssignee.map((row) => {
340	                        const member = members.find((m) => m.user_id === row.user_id);
341	                        const label = member?.email ?? row.user_id.slice(0, 8) + "…";
342	                        return (
343	                          <TableRow key={row.user_id}>
344	                            <TableCell className="text-sm font-medium">{label}</TableCell>
345	                            <TableCell className="text-sm text-right text-amber-600 dark:text-amber-400 font-medium">
346	                              {row.pending}
347	                            </TableCell>
348	                            <TableCell className="text-sm text-right text-emerald-600 dark:text-emerald-400 font-medium">
349	                              {row.completed}
350	                            </TableCell>
351	                          </TableRow>
352	                        );
353	                      })}
354	                    </TableBody>
355	                  </Table>
356	                </CardContent>
357	              </Card>
358	            )}
359	          </div>
360	        )}
361	
362	        {/* ── Pipeline Stages + Scorecard Templates + Automations (team admins/owners only) ── */}
363	        {team && canManage && (
364	          <div className="space-y-4 mb-6">
365	            <PipelineStageManager teamId={team.id} />
366	            <ScorecardTemplateManager teamId={team.id} />
367	            <StageAutomationManager teamId={team.id} />
368	          </div>
369	        )}
370	
371	        <div className="space-y-6">
372	          {/* Invite card — only visible to owners/admins */}
373	          {canManage && (
374	            <Card className="border border-border/60 shadow-sm">
375	              <CardHeader className="pb-3">
376	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
377	                  <UserPlus className="h-4 w-4 text-primary" />
378	                  Invite a teammate
379	                </CardTitle>
380	              </CardHeader>
381	              <CardContent>
382	                <form onSubmit={handleInvite} className="flex flex-col sm:flex-row gap-2">
383	                  <div className="relative flex-1">
384	                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
385	                    <Input
386	                      type="email"
387	                      placeholder="colleague@company.com"
388	                      value={inviteEmail}
389	                      onChange={(e) => setInviteEmail(e.target.value)}
390	                      className="pl-9"
391	                      required
392	                      disabled={isSendingInvite}
393	                    />
394	                  </div>
395	                  <Select
396	                    value={inviteRole}
397	                    onValueChange={(v) => setInviteRole(v as "admin" | "member")}
398	                    disabled={isSendingInvite}
399	                  >
400	                    <SelectTrigger className="w-full sm:w-32">
401	                      <SelectValue />
402	                    </SelectTrigger>
403	                    <SelectContent>
404	                      <SelectItem value="member">Member</SelectItem>
405	                      <SelectItem value="admin">Admin</SelectItem>
406	                    </SelectContent>
407	                  </Select>
408	                  <Button
409	                    type="submit"
410	                    disabled={isSendingInvite || !inviteEmail.trim()}
411	                    className="gap-1.5 shrink-0"
412	                  >
413	                    {isSendingInvite ? (
414	                      <Loader2 className="h-4 w-4 animate-spin" />
415	                    ) : (
416	                      <UserPlus className="h-4 w-4" />
417	                    )}
418	                    Send invite
419	                  </Button>
420	                </form>
421	              </CardContent>
422	            </Card>
423	          )}
424	
425	          {/* Pending invitations */}
426	          {(pendingInvitations.length > 0 || (isLoading && canManage)) && (
427	            <Card className="border border-border/60 shadow-sm">
428	              <CardHeader className="pb-3">
429	                <div className="flex items-center justify-between">
430	                  <CardTitle className="text-sm font-semibold flex items-center gap-2">
431	                    <Mail className="h-4 w-4 text-primary" />
432	                    Pending invitations
433	                    {!isLoading && (
434	                      <Badge variant="secondary" className="ml-1 text-xs">
435	                        {pendingInvitations.length}
436	                      </Badge>
437	                    )}
438	                  </CardTitle>
439	                  <Button
440	                    variant="ghost"
441	                    size="icon"
442	                    className="h-7 w-7"
443	                    onClick={() => refetch()}
444	                    disabled={isLoading}
445	                    aria-label="Refresh invitations"
446	                  >
447	                    <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
448	                  </Button>
449	                </div>
450	              </CardHeader>
451	              <CardContent className="p-0">
452	                {isLoading ? (
453	                  <div className="space-y-2 p-4">
454	                    {[1, 2].map((i) => (
455	                      <Skeleton key={i} className="h-10 w-full rounded-md" />
456	                    ))}
457	                  </div>
458	                ) : (
459	                  <Table>
460	                    <TableHeader>
461	                      <TableRow>
462	                        <TableHead className="text-xs">Email</TableHead>
463	                        <TableHead className="text-xs">Role</TableHead>
464	                        <TableHead className="text-xs">Expires</TableHead>
465	                        {canManage && <TableHead className="text-xs w-16" />}
466	                      </TableRow>
467	                    </TableHeader>
468	                    <TableBody>
469	                      {pendingInvitations.map((inv: TeamInvitation) => (
470	                        <TableRow key={inv.id}>
471	                          <TableCell className="text-sm font-medium">{inv.email}</TableCell>
472	                          <TableCell>
473	                            <RoleBadge role={inv.role} />
474	                          </TableCell>
475	                          <TableCell className="text-xs text-muted-foreground">
476	                            {format(new Date(inv.expires_at), "MMM d, yyyy")}
477	                          </TableCell>
478	                          {canManage && (
479	                            <TableCell>
480	                              <Button
481	                                variant="ghost"
482	                                size="icon"
483	                                className="h-7 w-7 text-muted-foreground hover:text-destructive"
484	                                onClick={() => handleRevokeInvite(inv.id, inv.email)}
485	                                disabled={revokingId === inv.id}
486	                                aria-label={`Revoke invite for ${inv.email}`}
487	                              >
488	                                {revokingId === inv.id ? (
489	                                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
490	                                ) : (
491	                                  <Trash2 className="h-3.5 w-3.5" />
492	                                )}
493	                              </Button>
494	                            </TableCell>
495	                          )}
496	                        </TableRow>
497	                      ))}
498	                    </TableBody>
499	                  </Table>
500	                )}
501	              </CardContent>
502	            </Card>
503	          )}
504	
505	          {/* Members table */}
506	          <Card className="border border-border/60 shadow-sm">
507	            <CardHeader className="pb-3">
508	              <div className="flex items-center justify-between">
509	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
510	                  <Users className="h-4 w-4 text-primary" />
511	                  Members
512	                  {!isLoading && (
513	                    <Badge variant="secondary" className="ml-1 text-xs">
514	                      {members.length}
515	                    </Badge>
516	                  )}
517	                </CardTitle>
518	                <Button
519	                  variant="ghost"
520	                  size="icon"
521	                  className="h-7 w-7"
522	                  onClick={() => refetch()}
523	                  disabled={isLoading}
524	                  aria-label="Refresh members"
525	                >
526	                  <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
527	                </Button>
528	              </div>
529	            </CardHeader>
530	            <CardContent className="p-0">
531	              {isLoading ? (
532	                <MembersSkeleton />
533	              ) : members.length === 0 ? (
534	                <div className="flex flex-col items-center justify-center py-12 space-y-3 text-center px-4">
535	                  <div className="rounded-xl bg-muted/50 p-4">
536	                    <Users className="h-7 w-7 text-muted-foreground/50" />
537	                  </div>
538	                  <div className="space-y-1">
539	                    <p className="text-sm font-medium text-foreground">No team yet</p>
540	                    <p className="text-sm text-muted-foreground max-w-xs">
541	                      Invite a colleague above to start collaborating on job rankings.
542	                    </p>
543	                  </div>
544	                </div>
545	              ) : (
546	                <Table>
547	                  <TableHeader>
548	                    <TableRow>
549	                      <TableHead className="text-xs">Member</TableHead>
550	                      <TableHead className="text-xs">Role</TableHead>
551	                      <TableHead className="text-xs">Joined</TableHead>
552	                      {canManage && <TableHead className="text-xs w-12" />}
553	                    </TableRow>
554	                  </TableHeader>
555	                  <TableBody>
556	                    {members.map((member: TeamMember) => {
557	                      const isCurrentUser = member.user_id === user?.id;
558	                      const isOwner = member.role === "owner";
559	                      return (
560	                        <TableRow key={member.id}>
561	                          <TableCell>
562	                            <div className="flex flex-col">
563	                              <span className="text-sm font-medium">
564	                                {member.email ?? member.user_id.slice(0, 8) + "…"}
565	                                {isCurrentUser && (
566	                                  <span className="ml-1.5 text-xs text-muted-foreground font-normal">(you)</span>
567	                                )}
568	                              </span>
569	                            </div>
570	                          </TableCell>
571	                          <TableCell>
572	                            {canManage && !isOwner && !isCurrentUser ? (
573	                              <Select
574	                                value={member.role}
575	                                onValueChange={(v) => handleChangeRole(member, v as TeamRole)}
576	                                disabled={updatingRoleId === member.id}
577	                              >
578	                                <SelectTrigger className="h-7 w-28 text-xs border-0 bg-transparent px-0 focus:ring-0 focus:ring-offset-0">
579	                                  <SelectValue />
580	                                </SelectTrigger>
581	                                <SelectContent>
582	                                  <SelectItem value="admin">Admin</SelectItem>
583	                                  <SelectItem value="member">Member</SelectItem>
584	                                </SelectContent>
585	                              </Select>
586	                            ) : (
587	                              <RoleBadge role={member.role} />
588	                            )}
589	                          </TableCell>
590	                          <TableCell className="text-xs text-muted-foreground">
591	                            {format(new Date(member.joined_at), "MMM d, yyyy")}
592	                          </TableCell>
593	                          {canManage && (
594	                            <TableCell>
595	                              {!isOwner && !isCurrentUser && (
596	                                <AlertDialog>
597	                                  <AlertDialogTrigger asChild>
598	                                    <Button
599	                                      variant="ghost"
600	                                      size="icon"
601	                                      className="h-7 w-7 text-muted-foreground hover:text-destructive"
602	                                      disabled={removingId === member.id}
603	                                      aria-label={`Remove ${member.email ?? "member"}`}
604	                                    >
605	                                      {removingId === member.id ? (
606	                                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
607	                                      ) : (
608	                                        <Trash2 className="h-3.5 w-3.5" />
609	                                      )}
610	                                    </Button>
611	                                  </AlertDialogTrigger>
612	                                  <AlertDialogContent>
613	                                    <AlertDialogHeader>
